"""Reader for the EU ledger export (semicolon-separated)."""
from meridian import text


def read_feed(path):
    """Read an EU feed: a list of {date, account, amount} rows."""
    rows = []
    with open(path, encoding="utf-8") as f:
        raw_lines = f.read().splitlines()
    fmt = text.feed_format(raw_lines)
    lines = [x for x in raw_lines if x and not x.startswith("#")]
    for line in lines[1:]:
        date, account, amount = line.split(";")
        rows.append({
            "date": date,
            "account": account,
            "amount": text.parse_amount(amount, fmt),
        })
    return rows
